/// <summary>
/// Dialog of Copy setup: lookup for the target environment.
/// </summary>
public final class BDRSetupCopyUIBuilder extends SysOperationAutomaticUIBuilder
{
    private DialogField targetEnvironmentField;
}

Method.Source:
    public void postBuild()
    {
        BDRSetupCopyContract contract = this.dataContractObject() as BDRSetupCopyContract;

        super();

        targetEnvironmentField = this.bindInfo().getDialogField(contract, methodStr(BDRSetupCopyContract, parmTargetEnvironmentId));

        targetEnvironmentField.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(BDRSetupCopyUIBuilder, lookupEnvironment), this);
    }

    /// <summary>
    /// Lists the environments by code and mode.
    /// </summary>
    public void lookupEnvironment(FormStringControl _control)
    {
        SysTableLookup lookup = SysTableLookup::newParameters(tableNum(BDREnvironment), _control);
        Query query = new Query();

        query.addDataSource(tableNum(BDREnvironment)).addSortField(fieldNum(BDREnvironment, EnvironmentId));

        lookup.addLookupfield(fieldNum(BDREnvironment, EnvironmentId), true);
        lookup.addLookupfield(fieldNum(BDREnvironment, EnvironmentMode));
        lookup.parmQuery(query);
        lookup.performFormLookup();
    }
